def solve(expr: str) -> int:
    """
    Evaluate a string arithmetic expression containing
    non‑negative integers and the operators +, -, *, / and parentheses.
    Division is integer floor division.
    No eval() is used.
    """
    import re

    # Tokenize the input
    tokens = re.findall(r'\d+|[()+\-*/]', expr)
    it = iter(tokens)

    def parse_expr() -> int:
        """Parse an expression (handles + and -)."""
        value = parse_term()
        while True:
            try:
                op = next(it)
            except StopIteration:
                break
            if op == '+':
                value += parse_term()
            elif op == '-':
                value -= parse_term()
            else:
                # Not a + or -, put it back for higher precedence parser
                it_back.append(op)
                break
        return value

    def parse_term() -> int:
        """Parse a term (handles * and /)."""
        value = parse_factor()
        while True:
            try:
                op = next(it)
            except StopIteration:
                break
            if op == '*':
                value *= parse_factor()
            elif op == '/':
                divisor = parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                value //= divisor
            else:
                it_back.append(op)
                break
        return value

    def parse_factor() -> int:
        """Parse a factor (number or parenthesized expression)."""
        try:
            token = next(it)
        except StopIteration:
            raise ValueError("unexpected end of expression")

        if token == '(':
            value = parse_expr()
            if next(it) != ')':
                raise ValueError("missing closing parenthesis")
            return value
        elif token.isdigit():
            return int(token)
        else:
            raise ValueError(f"unexpected token: {token}")

    # A simple stack to push back tokens when higher precedence parser
    it_back = []

    # Wrapper to handle the back‑stack
    def next(it_iter):
        if it_back:
            return it_back.pop()
        return next(it_iter)

    # Replace the built‑in next with our wrapper
    it = iter(tokens)
    next = lambda it_iter=it: next(it_iter)

    return parse_expr()
