class LRUCache:
    """Least Recently Used (LRU) Cache with O(1) operations."""
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}          # key -> node
        self.head = None         # most recently used
        self.tail = None         # least recently used

    # Node for doubly linked list
    class _Node:
        __slots__ = ("key", "value", "prev", "next")
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.prev = None
            self.next = None

    def _move_to_front(self, node):
        """Move an existing node to the head (most recent)."""
        if node is self.head:
            return
        # detach node
        if node.prev:
            node.prev.next = node.next
        if node.next:
            node.next.prev = node.prev
        if node is self.tail:
            self.tail = node.prev

        # insert at head
        node.prev = None
        node.next = self.head
        if self.head:
            self.head.prev = node
        self.head = node
        if self.tail is None:
            self.tail = node

    def _add_to_front(self, node):
        """Add a new node at the head."""
        node.prev = None
        node.next = self.head
        if self.head:
            self.head.prev = node
        self.head = node
        if self.tail is None:
            self.tail = node

    def _remove_tail(self):
        """Remove the least recently used node (tail)."""
        if not self.tail:
            return
        key = self.tail.key
        if self.tail.prev:
            self.tail.prev.next = None
        else:
            self.head = None
        self.tail = self.tail.prev
        del self.cache[key]

    def get(self, key: int) -> int:
        """Return value for key if present, else -1. Marks key as recent."""
        node = self.cache.get(key)
        if node is None:
            return -1
        self._move_to_front(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        """Insert or update key with value. Evict LRU if capacity exceeded."""
        node = self.cache.get(key)
        if node:
            node.value = value
            self._move_to_front(node)
        else:
            if len(self.cache) >= self.capacity:
                self._remove_tail()
            new_node = self._Node(key, value)
            self._add_to_front(new_node)
            self.cache[key] = new_node
