def split_fields(line):
    """
    Split a single CSV line on commas, respecting double‑quoted fields.
    - Commas inside quotes are ignored.
    - Double quotes inside a quoted field ("") become a single quote.
    - Surrounding quotes are removed.
    - An empty line returns [''].
    """
    if line == "":
        return [""]

    fields = []
    field = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Possible end of quoted field or escaped quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1  # Skip the escaped quote
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field))
                field = []
            elif ch == '"':
                in_quotes = True
            else:
                field.append(ch)
        i += 1

    # Append the last field
    fields.append(''.join(field))
    return fields
