def split_fields(line: str) -> list[str]:
    """
    Split a CSV line on commas while respecting quoted fields.
    - Commas inside double quotes do not split.
    - Double double‑quotes inside a quoted field are treated as a literal quote.
    - Surrounding quotes are removed.
    An empty line returns [''].
    """
    if line == "":
        return [""]

    fields = []
    buf = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Peek at next character to see if it's another quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    buf.append('"')
                    i += 1  # Skip the escaped quote
                else:
                    in_quotes = False
            else:
                buf.append(ch)
        else:
            if ch == ',':
                fields.append("".join(buf))
                buf.clear()
            elif ch == '"':
                in_quotes = True
            else:
                buf.append(ch)
        i += 1

    # Append the last field
    fields.append("".join(buf))
    return fields
